d_admin ON volunteer_assignments;CREATE POLICY va_read_admin ON public.volunteer_assignments FOR SELECT  TO authenticated USING (    public.get_my_role() IN ('super_admin', 'admin')  );DROP POLICY IF EXISTS va_insert ON volunteer_assignments;CREATE POLICY va_insert ON public.volunteer_assignments FOR INSERT  TO authenticated WITH CHECK (    public.get_my_role() IN ('super_admin', 'admin')  );DROP POLICY IF EXISTS va_update ON volunteer_assignments;CREATE POLICY va_update ON public.volunteer_assignments FOR UPDATE  TO authenticated USING (    public.get_my_role() IN ('super_admin', 'admin')  );CREATE OR REPLACE FUNCTION public.admin_toggle_role(  target_user_id uuid,  new_role text)RETURNS voidLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  caller_role text;  caller_level integer;  target_level integer;  new_role_level integer;BEGIN  IF target_user_id = auth.uid() THEN    RAISE EXCEPTION 'You cannot change your own role';  END IF;  SELECT role INTO caller_role FROM public.profiles WHERE id = auth.uid();  SELECT level INTO caller_level FROM public.roles WHERE name = caller_role;  IF caller_role NOT IN ('super_admin', 'admin') THEN    RAISE EXCEPTION 'Permission denied';  END IF;  SELECT level INTO new_role_level FROM public.roles WHERE name = new_role;  IF new_role_level IS NULL THEN    RAISE EXCEPTION 'Invalid role: %', new_role;  END IF;  SELECT COALESCE(r.level, 0) INTO target_level  FROM public.profiles p  LEFT JOIN public.roles r ON r.name = p.role  WHERE p.id = target_user_id;  IF target_level >= 100 THEN    RAISE EXCEPTION 'Cannot modify super admin accounts';  END IF;  IF new_role_level >= caller_level THEN    RAISE EXCEPTION 'Cannot assign role at or above your own level';  END IF;  UPDATE public.profiles  SET role = new_role, updated_at = now()  WHERE id = target_user_id;END;$$;CREATE OR REPLACE FUNCTION public.handle_new_user()RETURNS triggerLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$BEGIN  INSERT INTO public.profiles (id, email, full_name, country, role, status)  VALUES (    NEW.id,    COALESCE(NEW.email, ''),    COALESCE(NEW.raw_user_meta_data->>'full_name', 'Donor'),    COALESCE(NEW.raw_user_meta_data->>'country', ''),    'donor',    'active'  );  RETURN NEW;END;$$;DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;CREATE TRIGGER on_auth_user_created  AFTER INSERT ON auth.users  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();CREATE INDEX IF NOT EXISTS idx_donation_goals_active ON public.donation_goals(is_active);CREATE INDEX IF NOT EXISTS idx_testimonials_published ON public.testimonials(is_published);CREATE INDEX IF NOT EXISTS idx_events_date ON public.events(date);CREATE INDEX IF NOT EXISTS idx_timeline_sponsorship ON public.sponsorship_timeline(sponsorship_id);CREATE INDEX IF NOT EXISTS idx_certificates_user ON public.certificates(user_id);CREATE INDEX IF NOT EXISTS idx_login_history_user ON public.login_history(user_id, created_at DESC);CREATE INDEX IF NOT EXISTS idx_impact_metrics_month ON public.impact_metrics(month DESC);CREATE INDEX IF NOT EXISTS idx_teacher_assignments_teacher ON public.teacher_assignments(teacher_id);CREATE INDEX IF NOT EXISTS idx_teacher_assignments_student ON public.teacher_assignments(student_id);CREATE INDEX IF NOT EXISTS idx_student_progress_student ON public.student_progress(student_id);CREATE INDEX IF NOT EXISTS idx_attendance_student_date ON public.attendance_records(student_id, date);INSERT INTO public.testimonials (author_name, author_role, content, quote, is_published, sort_order) VALUES  (    'Sarah Johnson',    'Donor from Australia',    'Sponsoring Rajesh has been the most rewarding experience of my life. Seeing his grades improve and knowing he now dreams of becoming a doctor fills my heart with joy.',    'Every child deserves a chance to dream.',    true, 1  ),  (