es with basic instruments and supplies.',    25000, 7200, 15, 'Music', 'pink', 'education', true  )ON CONFLICT DO NOTHING;INSERT INTO public.impact_metrics (month, meals_funded, books_distributed, uniforms_provided, students_supported, attendance_rate) VALUES  ('2026-01-01', 2850, 320, 45, 187, 94.5),  ('2026-02-01', 3100, 280, 38, 192, 95.2),  ('2026-03-01', 2950, 350, 52, 195, 93.8),  ('2026-04-01', 3200, 300, 41, 198, 96.1),  ('2026-05-01', 3400, 380, 55, 203, 95.7),  ('2026-06-01', 3300, 340, 48, 200, 94.9)ON CONFLICT (month) DO NOTHING;INSERT INTO public.events (title, description, event_type, date, location, is_published) VALUES  ('Annual Sports Day 2026', 'A day of athletic competitions, team games, and celebrations of physical education.', 'sports', '2026-03-15', 'School Ground', true),  ('Nepali New Year Celebration', 'Cultural program featuring traditional music, dance, and food from all regions of Nepal.', 'celebration', '2026-04-13', 'School Hall', true),  ('Art Exhibition', 'Showcasing paintings, crafts, and creative works by students from all grades.', 'activity', '2026-02-20', 'Community Hall', true),  ('Parent-Teacher Meeting', 'Quarterly meeting to discuss student progress and school development.', 'program', '2026-05-10', 'School Auditorium', true),  ('Volunteer Teaching Week', 'International volunteers join our classrooms for a week of collaborative learning.', 'volunteer', '2026-07-01', 'Buddha Academy', true),  ('Annual Day Function', 'Year-end celebration with cultural performances, awards, and recognition ceremony.', 'function', '2026-12-20', 'School Ground', true)ON CONFLICT DO NOTHING;DO $$BEGIN  IF NOT EXISTS (    SELECT 1 FROM pg_trigger    WHERE tgname = 'on_auth_user_created'  ) THEN    CREATE TRIGGER on_auth_user_created      AFTER INSERT ON auth.users      FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();  END IF;END $$;GRANT USAGE ON SCHEMA public TO anon, authenticated;GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated;GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated;GRANT ALL ON ALL FUNCTIONS IN SCHEMA public TO anon, authenticated;
